proc keyboardLayoutKey*(layout, code: string): (string, string, string) =
  ## What a printable `code` means under `layout`: (unshifted, shifted, altGr);
  ## empty strings for a code the layout has no character for. An unknown
  ## layout is the default.
  case layout
  of "gb": layoutKeyGb(code)
  of "de": layoutKeyDe(code)
  of "fr": layoutKeyFr(code)
  of "es": layoutKeyEs(code)
  of "it": layoutKeyIt(code)
  of "sv": layoutKeySv(code)
  of "da": layoutKeyDa(code)
  of "nb": layoutKeyNb(code)
  else: layoutKeyUs(code)
